void dst_bus_dis (void * arg)
{ 
  if(!dst_bus_vars.flg_gwr)
    {
      dst_bus_vars.flg_gwr = TRUE ;
      
      BYPASS_RELAY_SET   ;

      BYPASS_PULL_UP_SET ;

      #if DBG_DST_BUS == 1
        dst_bus_dbg_print ("\nDst Bus Gwr On", NULL , NULL) ;
      #endif

    }
}
